package com.tnr.cityguide.storage;
import com.cloudinary.Cloudinary;import com.cloudinary.utils.ObjectUtils;import com.tnr.cityguide.config.AppProperties;
import java.io.IOException;import java.net.URI;import java.nio.file.*;import java.util.Map;
import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;
@Service public class CloudinaryStorageService implements StorageService {
 private final Cloudinary cloudinary;private final Path legacyRoot;
 public CloudinaryStorageService(AppProperties p){var c=p.cloudinary();legacyRoot=Path.of(p.storage().localDir()).toAbsolutePath().normalize();cloudinary=(c==null||blank(c.cloudName())||blank(c.apiKey())||blank(c.apiSecret()))?null:new Cloudinary(ObjectUtils.asMap("cloud_name",c.cloudName(),"api_key",c.apiKey(),"api_secret",c.apiSecret(),"secure",true));}
 public StoredImage store(String folder,MultipartFile file,long maxBytes){if(file==null||file.isEmpty()||file.getSize()>maxBytes)throw invalid(maxBytes);try{byte[] bytes=file.getBytes();return upload(bytes,folder,maxBytes);}catch(IOException e){throw new IllegalStateException("Could not read uploaded image.",e);}}
 public StoredImage migrateLegacy(String legacyUrl,String folder,long maxBytes){String path;try{path=URI.create(legacyUrl).getPath();}catch(Exception e){path=legacyUrl;}if(path==null)path=legacyUrl;int marker=path.indexOf("/uploads/");if(marker<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This is not a local upload URL.");Path source=legacyRoot.resolve(path.substring(marker+"/uploads/".length())).normalize();if(!source.startsWith(legacyRoot))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid legacy image path.");try{if(!Files.isRegularFile(source))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Legacy image file is not available on this server.");long size=Files.size(source);if(size<=0||size>maxBytes)throw invalid(maxBytes);return upload(Files.readAllBytes(source),folder,maxBytes);}catch(IOException e){throw new IllegalStateException("Could not read legacy image.",e);}}
 private StoredImage upload(byte[] bytes,String folder,long maxBytes){if(bytes.length==0||bytes.length>maxBytes||!valid(bytes))throw invalid(maxBytes);if(cloudinary==null)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Cloudinary is not configured. Set CLOUDINARY_CLOUD_NAME, CLOUDINARY_API_KEY and CLOUDINARY_API_SECRET on the backend.");try{String safe="city-guide/"+(folder==null?"misc":folder.replaceAll("[^a-zA-Z0-9/_-]",""));Map result=cloudinary.uploader().upload(bytes,ObjectUtils.asMap("folder",safe,"resource_type","image","overwrite",false,"unique_filename",true,"use_filename",false));String url=String.valueOf(result.get("secure_url")),id=String.valueOf(result.get("public_id"));if("null".equals(url)||"null".equals(id))throw new IllegalStateException("Cloudinary returned incomplete image details.");return new StoredImage(url,id);}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new IllegalStateException("Image upload to Cloudinary failed.",e);}}
 public void delete(String publicId){if(publicId==null||publicId.isBlank())return;if(cloudinary==null)throw new IllegalStateException("Cloudinary is not configured.");try{Map result=cloudinary.uploader().destroy(publicId,ObjectUtils.asMap("invalidate",true,"resource_type","image"));Object status=result.get("result");if(status!=null&&!"ok".equals(status)&&!"not found".equals(status))throw new IllegalStateException("Cloudinary did not confirm image deletion.");}catch(Exception e){throw new IllegalStateException("Could not delete image from Cloudinary.",e);}}
 private boolean valid(byte[] b){return(b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255)||(b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71&&b[4]==13&&b[5]==10&&b[6]==26&&b[7]==10)||(b.length>=12&&b[0]=='R'&&b[1]=='I'&&b[2]=='F'&&b[3]=='F'&&b[8]=='W'&&b[9]=='E'&&b[10]=='B'&&b[11]=='P');}
 private ResponseStatusException invalid(long max){return new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a JPEG, PNG or WebP image no larger than "+(max/1024/1024)+" MB.");}private boolean blank(String s){return s==null||s.isBlank();}
}